    if (mm > 0 && !gone) ell(g, sx, sy, r, r * .8, { f: '#ffffff', blur: kub ? 2 : 0 }); if (gone) dots(g, 6, sx, sy + 20, 12, 16, 1.6, '#fff', 19);
    noise(g, kub ? .5 : .35, 'overlay', kub ? 1.3 : 1.1);
    const L = s.L; if (mm > 0 && !gone) L(sx, sy, '輸尿管結石 ' + mm + ' mm', 'Ureteric stone ' + mm + ' mm', 100, 230, '#ffb3b3'); if (gone) L(sx, sy + 20, '碎石後的粉末／碎片', 'Stone dust / fragments', 100, 230, '#9f9'); if (hyd > .2) L(170, 150, '腎盂擴張（水腎）', 'Dilated pelvis (hydronephrosis)', 90, 96, '#ffb3b3'); else L(170, 150, '右腎', 'Right kidney', 90, 96); L(470, 150, '左腎（正常）', 'Left kidney (normal)', 560, 60); L(320, 430, '膀胱', 'Bladder', 560, 440); if (stent) L(320, 440, '雙 J 導管（腎盂到膀胱）', 'JJ stent (pelvis to bladder)', 560, 380, '#9f9');
