      if (rup) { shape(g, [[ax - 40, ay - 30], [ax - 120, ay + 10], [ax - 150, ay + 90], [ax - 60, ay + 70], [ax - 10, ay + 40]], { f: grey(95), blur: 14 }); dots(g, 20, ax - 90, ay + 40, 60, 40, 12, grey(140, .3), 33, 8); }
      ell(g, ax, ay, r, r, { f: grey(120), s: grey(200), lw: 2 }); if (d > 3.5) ell(g, ax - r * .15, ay + r * .1, r * .85, r * .85, { f: grey(80) }); ell(g, ax + r * .18, ay - r * .12, Math.min(r * .6, 14 + r * .2), Math.min(r * .6, 14 + r * .2), { f: grey(225) });
      if (rup) ell(g, ax - r * .7, ay + r * .3, 8, 6, { f: grey(240) }); if (d > 5) { const R = rng(12); for (let i = 0; i < 10; i++) { const a = R() * TAU; ell(g, ax + Math.cos(a) * r * .96, ay + Math.sin(a) * r * .96, 3, 2, { f: '#fff', rot: a }); } }
